#include "../src/registration.hpp"
#include <iostream>
int wmain(int argc,wchar_t** argv){if(argc!=3)return 2;auto a=readModel(argv[1]),b=readModel(argv[2]);double span=std::max({a.hi.x-a.lo.x,a.hi.y-a.lo.y,b.hi.x-b.lo.x,b.hi.y-b.lo.y});registration::SurfaceCloud aa(registration::steepSurfaces(a,span/300)),bb(registration::steepSurfaces(b,span/300));CompareOptions o;o.angle=-.2954617267;o.dx=-380.5023729;o.dy=-29.71209586;o.dz=-35.26961042;std::cout<<aa.tree.nodes.size()<<" "<<bb.tree.nodes.size()<<" span "<<span<<'\n';auto print=[&](CompareOptions p){auto s=registration::structuralScore(aa,bb,p,span);std::cout<<p.angle<<","<<p.dx<<","<<p.dy<<" score "<<s.cost<<" coverage "<<s.coverage<<" spread "<<s.spread<<" rms "<<s.rms<<'\n';};print(o);for(double offset:{0.,-.08,-.04,.04,.08}){auto seed=o;seed.dx+=offset*span;print(registration::fitStructure(aa,bb,seed,span));}}
